using System;
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
public static class ReplicaMailBuilder {
 const string Root="Assets/GooseReplica/Resources/Replica/";
 static Font Font=>AssetDatabase.LoadAssetAtPath<Font>(Root+"Fonts/GooseSans.otf");
 public static RectTransform Rect(string n,Transform p,float x,float y,float w,float h){var r=new GameObject(n,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(p,false);r.sizeDelta=new Vector2(w,h);r.anchoredPosition=new Vector2(x,y);return r;}
 static Sprite Sprite(string n)=>AssetDatabase.LoadAssetAtPath<Sprite>(Root+"MailSkinPS/"+n+".png");
 static Image Pic(string n,string asset,Transform p,float x,float y,float w,float h){var im=Rect(n,p,x,y,w,h).gameObject.AddComponent<Image>();im.sprite=Sprite(asset);im.raycastTarget=false;return im;}
 static Text Text(string n,Transform p,float x,float y,float w,float h,string value,int size,Color? color=null){var t=Rect(n,p,x,y,w,h).gameObject.AddComponent<Text>();t.font=Font;t.text=value;t.fontSize=size;t.fontStyle=FontStyle.Bold;t.color=color??new Color32(32,118,185,255);t.alignment=TextAnchor.MiddleCenter;t.raycastTarget=false;t.supportRichText=false;t.horizontalOverflow=HorizontalWrapMode.Wrap;return t;}
 static Button Button(Image im){im.raycastTarget=true;var b=im.gameObject.AddComponent<Button>();b.targetGraphic=im;return b;}
 static Button TextButton(string n,Transform p,float x,float y,float w,float h,string caption){var b=Button(Pic(n,"image_btn_blue02 拷贝 15",p,x,y,w,h));Text("Label",b.transform,0,3,w-20,h-10,caption,23,Color.white);return b;}
 static RectTransform RootView(string name,out RectTransform content,out ReplicaUIView ui){var root=Rect(name,null,0,0,720,1280);var shade=root.gameObject.AddComponent<Image>();shade.color=new Color(0,0,0,.65f);content=Rect("Content - edit UI here",root,0,0,720,1280);root.gameObject.AddComponent<ReplicaUIFitContent>().content=content;ui=root.gameObject.AddComponent<ReplicaUIView>();return root;}
 static ReplicaUIView.Binding Bind(string key,Component c)=>new ReplicaUIView.Binding{key=key,target=c.gameObject};
 static void Save(RectTransform root,string name){PrefabUtility.SaveAsPrefabAsset(root.gameObject,Root+"UI/"+name+".prefab");UnityEngine.Object.DestroyImmediate(root.gameObject);}
 static ScrollRect Scroll(string name,Transform p,float x,float y,float w,float h,out RectTransform content){var r=Rect(name,p,x,y,w,h);var im=r.gameObject.AddComponent<Image>();im.color=new Color(1,1,1,.001f);r.gameObject.AddComponent<RectMask2D>();var scroll=r.gameObject.AddComponent<ScrollRect>();scroll.viewport=r;scroll.horizontal=false;scroll.movementType=ScrollRect.MovementType.Clamped;scroll.scrollSensitivity=30;content=Rect("Content",r,0,0,w,h);content.anchorMin=new Vector2(0,1);content.anchorMax=Vector2.one;content.pivot=new Vector2(.5f,1);content.sizeDelta=new Vector2(0,h);scroll.content=content;return scroll;}
 [MenuItem("Goose Replica/UI/Build Mail System")]
 public static void Build(){
  AssetDatabase.Refresh();foreach(var id in AssetDatabase.FindAssets("t:Texture2D",new[]{Root+"MailSkinPS"})){var imp=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(id));imp.textureType=TextureImporterType.Sprite;imp.spriteImportMode=SpriteImportMode.Single;imp.spritePixelsPerUnit=100;imp.mipmapEnabled=false;imp.alphaIsTransparency=true;imp.isReadable=false;imp.maxTextureSize=1024;var platform=imp.GetDefaultPlatformTextureSettings();platform.maxTextureSize=1024;imp.SetPlatformTextureSettings(platform);imp.textureCompression=TextureImporterCompression.CompressedHQ;imp.SaveAndReimport();}
  Mailbox();Dialog();Menu();Badge();AssetDatabase.SaveAssets();
 }
 static void Mailbox(){var root=RootView("Mailbox",out var c,out var ui);var skin=root.gameObject.AddComponent<ReplicaMailboxView>();Pic("Envelope","image_Email_bg",c,0,0,578,940);Pic("Title","邮件",c,0,354,126,62);var close=Button(Pic("Close","img_exit_x",c,278,398,73,73));
  Scroll("Mail list",c,0,35,500,510,out var list);skin.list=list;var layout=list.gameObject.AddComponent<VerticalLayoutGroup>();layout.spacing=12;layout.childControlWidth=true;layout.childControlHeight=true;layout.childForceExpandHeight=false;list.gameObject.AddComponent<ContentSizeFitter>().verticalFit=ContentSizeFitter.FitMode.PreferredSize;
  var row=Pic("Mail row","image_BlueEmail_cube",list,0,0,500,116);row.raycastTarget=true;row.gameObject.AddComponent<LayoutElement>().preferredHeight=116;var button=Button(row);var rv=row.gameObject.AddComponent<ReplicaUIView>();var title=Text("Title",row.transform,-72,32,310,30,"道具发放通知（未读）",21);title.alignment=TextAnchor.MiddleLeft;title.horizontalOverflow=HorizontalWrapMode.Wrap;var date=Text("Date",row.transform,164,32,145,30,"10-30 12:00",19);var summary=Text("Summary",row.transform,0,-20,458,51,"您收到了一份道具奖励，点击查看。",21,new Color32(243,94,126,255));summary.alignment=TextAnchor.MiddleLeft;rv.bindings=new[]{Bind("Title",title),Bind("Date",date),Bind("Summary",summary),Bind("Open",button)};skin.rowTemplate=row.gameObject;row.gameObject.SetActive(false);
  skin.unread=Sprite("image_BlueEmail_cube");skin.read=Sprite("image_yellowEmail_cube");skin.status=Text("Status",c,0,-248,470,45,"",19);skin.refresh=TextButton("Refresh",c,-115,-304,190,76,"刷新邮件");skin.more=TextButton("More",c,115,-304,190,76,"加载更多");ui.bindings=new[]{Bind("Close",close)};Save(root,"Mailbox");
 }
 static void Dialog(){var root=RootView("CommonDialog",out var c,out var ui);var d=root.gameObject.AddComponent<ReplicaCommonDialog>();Pic("Background","image_pop-up_sky03",c,0,0,596,681);d.title=Text("Title",c,0,263,490,70,"道具领取",46,Color.white);d.title.resizeTextForBestFit=true;d.title.resizeTextMinSize=22;d.title.resizeTextMaxSize=46;var outline=d.title.gameObject.AddComponent<Outline>();outline.effectColor=new Color32(0,114,210,255);outline.effectDistance=new Vector2(3,-3);
  Scroll("Body scroll",c,0,27,470,340,out var body);var text=Text("Body",body,0,0,470,340,"领取内容",28);var rt=(RectTransform)text.transform;rt.anchorMin=Vector2.zero;rt.anchorMax=Vector2.one;rt.offsetMin=rt.offsetMax=Vector2.zero;text.alignment=TextAnchor.UpperLeft;var layout=body.gameObject.AddComponent<VerticalLayoutGroup>();layout.childControlWidth=true;layout.childControlHeight=true;layout.childForceExpandHeight=false;body.gameObject.AddComponent<ContentSizeFitter>().verticalFit=ContentSizeFitter.FitMode.PreferredSize;d.body=text;
  d.status=Text("Status",c,0,-177,470,48,"",20);d.left=Button(Pic("Cancel","image_btn_blue02 拷贝 15",c,-132,-255,230,117));d.right=Button(Pic("Confirm","image_btn_red02",c,132,-255,230,118));d.leftLabel=Text("Label",d.left.transform,0,4,210,65,"返回邮件",29,Color.white);d.rightLabel=Text("Label",d.right.transform,0,4,210,65,"确认领取",29,Color.white);d.close=Button(Pic("Close","img_exit_x",c,281,320,81,81));ui.bindings=new[]{Bind("Close",d.close)};Save(root,"CommonDialog");
 }
 static void Menu(){var root=Rect("HomeMenu",null,0,0,720,1280);root.anchorMin=Vector2.zero;root.anchorMax=Vector2.one;root.sizeDelta=Vector2.zero;var ui=root.gameObject.AddComponent<ReplicaUIView>();var skin=root.gameObject.AddComponent<ReplicaHomeMenu>();var shade=root.gameObject.AddComponent<Image>();shade.color=new Color(0,0,0,.25f);var dismiss=Button(shade);
  var panel=Pic("Menu panel","image_popupMenu_cube",root,-188,0,216,367);var pr=(RectTransform)panel.transform;pr.anchorMin=pr.anchorMax=new Vector2(.5f,1);pr.anchoredPosition=new Vector2(-188,-300);panel.raycastTarget=true;
  var bindings=new List<ReplicaUIView.Binding>{Bind("Dismiss",dismiss)};string[] keys={"Card","Settings","Mail","Service","Cash"},labels={"个人名片","系统设置","邮件通知","联系客服","提现记录"},icons={"card","setting","systemNotification","service","Cash-out"};
  for(int i=0;i<5;i++){var b=Button(Pic(keys[i],"组 12",panel.transform,0,135-i*68,182,60));Pic("Icon","image_btn_"+icons[i],b.transform,-60,0,30,30);Text("Label",b.transform,19,0,130,52,labels[i],27,Color.white);bindings.Add(Bind(keys[i],b));if(i==2)skin.mailDot=Pic("Unread","image_red dot",b.transform,86,25,22,22).gameObject;}
  ui.bindings=bindings.ToArray();Save(root,"HomeMenu");
 }
 static void Badge(){var path=Root+"UI/Home.prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var button=root.GetComponent<ReplicaUIView>().Get<Button>("Settings");var old=button.transform.Find("Mail badge");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);{var badge=Pic("Mail badge","image_red dot",button.transform,30,30,22,22);badge.gameObject.AddComponent<ReplicaMailBadge>();}PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
}
